<script setup lang="ts">import {ref,computed,onMounted} from 'vue';import {networks} from '../stores/networks';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import NetworkDiagram from '../components/NetworkDiagram.vue';const selected=ref('demo-network'),name=ref(''),description=ref(''),text=ref("[\n  {\n    \"node_id\": \"Fault\",\n    \"label\": \"故障假设\",\n    \"parents\": []\n  },\n  {\n    \"node_id\": \"Power\",\n    \"label\": \"供给异常假设\",\n    \"parents\": []\n  },\n  {\n    \"node_id\": \"Heat\",\n    \"label\": \"温升表征\",\n    \"parents\": [\n      \"Fault\",\n      \"Power\"\n    ]\n  },\n  {\n    \"node_id\": \"Vibration\",\n    \"label\": \"振动表征\",\n    \"parents\": [\n      \"Fault\"\n    ]\n  },\n  {\n    \"node_id\": \"Alarm\",\n    \"label\": \"告警表征\",\n    \"parents\": [\n      \"Heat\",\n      \"Vibration\"\n    ]\n  },\n  {\n    \"node_id\": \"Indicator\",\n    \"label\": \"弱指示表征\",\n    \"parents\": [\n      \"Power\"\n    ]\n  },\n  {\n    \"node_id\": \"Lock\",\n    \"label\": \"演练确定标记\",\n    \"parents\": [\n      \"Fault\"\n    ]\n  }\n]");const {error,busy,act}=useTask();onMounted(networks.load);const graph=computed(()=>networks.items.value.find(n=>n.id===selected.value));function submit(){act(async()=>{const r=await networks.create({name:name.value,description:description.value,nodes_json:text.value});selected.value=r.id;name.value=''})}</script><template><PageHeading index="01 / 给定网络" title="先审结构，再讨论概率。" note="1–10个二元节点，最多4个父节点；节点唯一、父节点已知且无环。父节点数组顺序决定CPT父配置顺序。"/><div class="two-col"><section><label>研修网络<select v-model="selected"><option v-for="n in networks.items.value" :key="n.id" :value="n.id">{{n.name}}</option></select></label><template v-if="graph"><h2>{{graph.name}}</h2><NetworkDiagram :nodes="graph.nodes"/><p class="method-note">拓扑顺序 {{graph.topological_order.join(' → ')}}<br>{{graph.description}}</p></template></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>记录给定DAG</h2><label>网络名称<input v-model="name" required minlength="2"></label><label>节点JSON<textarea v-model="text" rows="13" required></textarea></label><label>研修来源说明<input v-model="description"></label><Notice :message="error"/><button :disabled="busy">校验并保存网络</button></form></div></template>
